/* composed with, from 28-chip and 56-fold */
.section-label { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); margin-bottom: 10px; }
.chip { display: inline-flex; align-items: center; gap: 6px; box-sizing: border-box; height: 22px; padding: 0 10px; border-radius: var(--ds-r-badge, 4px); font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; white-space: nowrap; line-height: 1; border: 1px solid var(--border); color: var(--text-secondary); background: transparent; }
.chip.cyan { color: var(--cyan); border-color: color-mix(in srgb, var(--cyan) 35%, transparent); background: color-mix(in srgb, var(--cyan) 13%, transparent); }
.chip.green { color: var(--green); border-color: color-mix(in srgb, var(--green) 35%, transparent); background: color-mix(in srgb, var(--green) 13%, transparent); }
.chip.gold { color: var(--gold); border-color: color-mix(in srgb, var(--gold) 35%, transparent); background: color-mix(in srgb, var(--gold) 13%, transparent); }
.chip.red { color: var(--red); border-color: color-mix(in srgb, var(--red) 35%, transparent); background: color-mix(in srgb, var(--red) 13%, transparent); }
.chip.status { gap: 5px; height: auto; padding: 2px 8px; border-radius: var(--ds-r-pill); font-weight: 500; letter-spacing: 0; }
.chip.status::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: currentColor; flex: none; }
.row { display: flex; flex-wrap: wrap; gap: 8px; }
.folds { display: flex; flex-direction: column; gap: 8px; }
.fold-group { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 12px; margin: 16px 0 4px; }
.fold-group:first-child { margin-top: 0; }
.fold-group-name { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--text); }
.fold-group-note { color: var(--text-secondary); }
.fold { container-type: inline-size; background: var(--surface); border: 1px solid var(--border); border-radius: var(--ds-r-sm); }
.fold > summary { list-style: none; cursor: pointer; display: grid; grid-template-columns: minmax(0, 1fr) 16px; gap: 8px 16px; align-items: center; padding: 16px; }
.fold > summary::-webkit-details-marker { display: none; }
.fold > summary::after { content: ""; grid-column: 2; grid-row: 1; justify-self: end; width: 8px; height: 8px; border-right: 1.5px solid var(--text-secondary); border-bottom: 1.5px solid var(--text-secondary); transform: rotate(-45deg); transition: transform var(--dur-base) var(--ease-out); }
.fold[open] > summary::after { transform: rotate(45deg); }
.fold > summary:hover::after { border-color: var(--cyan); }
.fold > summary:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; border-radius: var(--ds-r-sm); }
.fold[open] > summary { border-bottom: 1px solid var(--border); }
.fold-title { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.fold-title h2 { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--text-secondary); }
.fold-verdict { color: var(--text); }
.fold > summary .chip { grid-column: 1; grid-row: 2; justify-self: start; }
@container (min-width: 38rem) { .fold > summary { grid-template-columns: minmax(0, 1fr) auto 16px; } .fold > summary::after { grid-column: 3; } .fold > summary .chip { grid-column: 2; grid-row: 1; justify-self: end; } }
.fold-body { padding: 16px 16px 20px; display: flex; flex-direction: column; gap: 12px; }
@media print { .fold > summary::after { display: none; } }
@media (prefers-reduced-motion: reduce) { .fold > summary::after { transition: none; } }
/* @prim:begin 70-week-plan */
.wp { --wp-fog: 0.5; --wp-key: 9.5rem; display: flex; flex-direction: column; gap: 16px; container-type: inline-size; }
.wp-k { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-secondary); }
.wp-hyp { background-image: radial-gradient(color-mix(in srgb, var(--text-secondary) calc(36% * var(--wp-fog)), transparent) 0.7px, transparent 0.9px); background-size: 5px 5px; }
.wp-fp { font-family: var(--ds-font-display); font-size: var(--fs-headline); line-height: 1.4; color: var(--text); display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; text-wrap: pretty; }
.wp-key { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; color: var(--text-secondary); font-size: var(--fs-body); }
.wp-keyg { display: inline-block; box-sizing: border-box; width: 22px; height: 14px; border: 1px solid var(--border); border-radius: var(--ds-r-xs); }
.wp-fp { padding: 12px 16px; border: 1px solid var(--border); border-radius: var(--ds-r-sm); background-color: var(--surface); }
.wp-src { display: block; font-size: var(--fs-body); color: var(--text-secondary); font-family: var(--ds-font-mono); letter-spacing: 0.02em; margin-top: 2px; }
.wp-tabs { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px; }
.wp-tab { display: flex; flex-direction: column; align-items: flex-start; gap: 4px; min-height: 44px; padding: 8px; font: inherit; text-align: left; color: var(--text); background: var(--glass, var(--surface)); box-shadow: var(--bevel, none), var(--lift, none); border: 1px solid var(--border); border-radius: var(--ds-r-sm); cursor: pointer; min-width: 0; }
.wp-tab[aria-selected="true"] { border-color: var(--cyan); box-shadow: inset 0 -2px 0 var(--cyan); }
.wp-tab:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }
.wp-tab-n { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; }
.wp-tab-s { font-size: var(--fs-body); color: var(--text-secondary); }
.wp-tspark { width: 100%; height: 20px; display: block; }
.wp-tspark line, .wp-strip line, .wp-fspark line, .wp-fspark polyline { fill: none; stroke-width: 2.5; stroke-linecap: round; }
.wp-tspark line { stroke-width: 2; }
.wp-cost { stroke: var(--orange); } .wp-pos { stroke: var(--green); } .wp-neg { stroke: var(--red); stroke-dasharray: 5 3; } .wp-flat, .wp-none { stroke: var(--dimmed); stroke-dasharray: 2 3; }
polyline.wp-on { stroke: var(--cyan); } polyline.wp-off { stroke: var(--dimmed); }
circle.wp-on { fill: var(--cyan); } circle.wp-off { fill: var(--bg); stroke: var(--dimmed); stroke-width: 2; }
.wp-panel { display: flex; flex-direction: column; gap: 20px; padding-top: 4px; }
.wp-panel[hidden] { display: none; }
.wp-panel:focus-visible { outline: 2px solid var(--cyan); outline-offset: 4px; }
.wp-wh { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--text-secondary); }
.wp-pills { list-style: none; display: flex; flex-wrap: wrap; gap: 8px; }
.wp-pills li { display: inline-flex; align-items: baseline; gap: 8px; padding: 4px 10px; border: 1px solid var(--border); border-radius: var(--ds-r-sm); font-family: var(--ds-font-mono); font-size: var(--fs-label); }
.wp-pills span { color: var(--text-secondary); letter-spacing: 0.1em; text-transform: uppercase; } .wp-pills b { color: var(--text); font-weight: 700; }
.wp-block { display: flex; flex-direction: column; gap: 10px; }
.wp-legend { list-style: none; display: flex; flex-wrap: wrap; gap: 4px 14px; font-family: var(--ds-font-mono); font-size: var(--fs-label); color: var(--text-secondary); }
.wp-legend i { display: inline-block; width: 12px; height: 3px; margin-right: 6px; vertical-align: middle; }
.wp-legend i.wp-cost { background: var(--orange); } .wp-legend i.wp-stop { background: var(--gold); height: 8px; width: 6px; } .wp-legend i.wp-pos { background: var(--green); } .wp-legend i.wp-neg { background: var(--red); } .wp-legend i.wp-flat { height: 0; border-top: 2px dashed var(--dimmed); }
.wp-legend i.wp-on { background: var(--cyan); height: 8px; width: 8px; border-radius: 50%; } .wp-legend i.wp-off { background: transparent; border: 2px solid var(--dimmed); box-sizing: border-box; height: 8px; width: 8px; border-radius: 50%; } .wp-legend i.wp-forki { background: var(--gold); width: 2px; height: 12px; }
.wp-stripwrap { overflow-x: auto; padding: 12px; border: 1px solid var(--border); border-radius: var(--ds-r-sm); background: var(--deboss-fill, var(--surface)); box-shadow: var(--deboss, none); }
.wp-strip { width: 100%; min-width: 34rem; height: auto; display: block; }
.wp-strip text { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.06em; fill: var(--text-secondary); }
.wp-strip .wp-lane { fill: var(--text); }
.wp-strip .wp-fork { stroke: var(--gold); stroke-width: 1; stroke-dasharray: 2 3; }
.wp-strip .wp-fork.is-kill { stroke: var(--red); stroke-width: 2; stroke-dasharray: none; }
.wp-strip .wp-forkl { fill: var(--gold); }
.wp-stop { fill: var(--gold); }
.wp-strip .wp-post { fill: var(--green); } .wp-strip .wp-negt { fill: var(--red); } .wp-strip .wp-flatt { fill: var(--text-secondary); }
.wp-fid { color: var(--text-secondary); font-size: var(--fs-body); }
.wp-notes { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.wp-note, .wp-fork-card { position: relative; display: flex; flex-direction: column; gap: 8px; padding: 12px 14px; border: 1px solid color-mix(in srgb, var(--wp-c, var(--border)) 45%, var(--border)); border-radius: var(--ds-r-sm); background-color: var(--surface); min-width: 0; }
.wp-n-best { --wp-c: var(--green); } .wp-n-base { --wp-c: var(--cyan); } .wp-n-worst { --wp-c: var(--red); }
.wp-note-h { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.wp-note .wp-best, .wp-k.wp-post { color: var(--green); } .wp-note .wp-base { color: var(--cyan); } .wp-note .wp-worst, .wp-k.wp-negt { color: var(--red); }
.wp-k.wp-costt { color: var(--orange); } .wp-k.wp-stopt, .wp-k.wp-forkt { color: var(--gold); } .wp-k.wp-ont { color: var(--cyan); } .wp-k.wp-offt, .wp-k.wp-flatt { color: var(--text-secondary); }
.wp-dl { display: grid; grid-template-columns: minmax(0, 1fr); gap: 2px; margin: 0; }
.wp-dl dd { margin: 0 0 6px; color: var(--text); text-wrap: pretty; }
.wp-pm > summary { list-style: none; cursor: pointer; min-height: 44px; display: flex; align-items: center; gap: 8px; color: var(--cyan); font-size: var(--fs-body); text-decoration: underline; text-underline-offset: 3px; }
.wp-pm > summary::-webkit-details-marker { display: none; }
.wp-pm > summary::before { content: "+"; font-family: var(--ds-font-mono); font-weight: 700; text-decoration: none; }
.wp-pm[open] > summary::before { content: "\2212"; }
.wp-pm > summary:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }
.wp-pm ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.wp-fals { display: block; font-size: var(--fs-body); color: var(--text-secondary); }
.wp-pmtext { margin-top: 8px; font-style: italic; }
.wp-cascade { display: flex; flex-direction: column; margin: 0; border: 1px solid var(--border); border-radius: var(--ds-r-sm); background-color: var(--surface); }
.wp-crow { display: grid; grid-template-columns: var(--wp-key) minmax(0, 1fr); column-gap: 16px; align-items: baseline; padding: 12px 14px; }
.wp-crow + .wp-crow { border-top: 1px solid var(--border); }
.wp-crow dt::before { content: ""; display: inline-block; width: 8px; height: 8px; margin-right: 8px; border-radius: var(--ds-r-pill); background: currentColor; vertical-align: 1px; }
.wp-crow dt { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--wp-c); }
.wp-crow dd { margin: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; color: var(--text); }
.wp-crow dd > span:first-child { flex: 1 1 100%; text-wrap: pretty; }
.wp-crow dd > .wp-src { flex: 1 1 100%; margin-top: 0; }
.wp-crow-tags { display: inline-flex; flex-wrap: wrap; gap: 6px; }
.wp-a-executive { --wp-c: var(--green); } .wp-a-strategic { --wp-c: var(--cyan); } .wp-a-operational { --wp-c: var(--gold); } .wp-a-tactical { --wp-c: var(--orange); } .wp-a-surgical { --wp-c: var(--red); }
.wp-ftag { display: inline-flex; align-items: center; min-height: 22px; padding: 0 8px; border: 1px dashed var(--gold); border-radius: var(--ds-r-xs); font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; color: var(--gold); text-decoration: none; }
.wp-ftag:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }
.wp-forks { display: grid; grid-template-columns: minmax(0, 1fr); align-items: start; gap: 8px; }
@container (min-width: 56rem) { .wp-forks { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.wp-fork-card { --wp-c: var(--gold); scroll-margin-top: 96px; }
.wp-fork-card.is-kill { --wp-c: var(--red); }
.wp-fork-h { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px; }
.wp-fork-q { font-size: var(--fs-body); font-weight: 600; line-height: 1.45; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 8px; }
.wp-sw { display: inline-flex; border: 1px solid var(--border); border-radius: var(--ds-r-sm); overflow: hidden; }
.wp-swb { min-height: 44px; min-width: 56px; padding: 0 12px; font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--text-secondary); background: transparent; border: 0; cursor: pointer; }
.wp-swb[data-v="keep"][aria-pressed="true"] { color: var(--green); background: var(--green-bg); box-shadow: inset 0 0 0 1px var(--green); }
.wp-swb[data-v="kill"][aria-pressed="true"] { color: var(--red); background: var(--red-bg); box-shadow: inset 0 0 0 1px var(--red); }
.wp-swb:focus-visible { outline: 2px solid var(--cyan); outline-offset: -2px; }
.wp-fspark { width: 100%; height: auto; display: block; }
.wp-fspark .wp-base { stroke: var(--border); stroke-width: 1; }
.wp-fspark .wp-stopl { stroke: var(--gold); stroke-width: 1; stroke-dasharray: 3 3; }
.wp-fspark .wp-forkc { fill: none; stroke: var(--gold); stroke-width: 1.5; }
.wp-fspark .wp-kill { stroke-width: 1.5; stroke-dasharray: 4 3; } .wp-fork-card.is-kill .wp-fspark .wp-kill { stroke-width: 3; } .wp-fork-card.is-kill .wp-fspark .wp-keep { stroke-opacity: 0.35; }
.wp-fspark .wp-ontick { fill: var(--cyan); }
.wp-prem li { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 8px; padding: 6px 8px; border-radius: var(--ds-r-xs); }
.wp-live:empty { display: none; } .wp-live { font-size: var(--fs-body); color: var(--text-secondary); }
.wp-tree, .wp-tree ol { list-style: none; display: flex; flex-direction: column; gap: 6px; }
.wp-tree ol { margin: 6px 0 0 12px; padding-left: 12px; border-left: 1px solid var(--border); }
.wp-tree li { display: block; padding: 4px 6px; border-radius: var(--ds-r-xs); }
.wp-tree + .wp-tree { margin-top: 16px; padding-top: 16px; border-top: 1px solid var(--border); }
.wp-ord { display: inline-flex; justify-content: center; min-width: 22px; margin-right: 8px; font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; color: var(--cyan); }
.wp-mx-wrap { display: grid; grid-template-columns: minmax(18rem, 24rem) minmax(0, 1fr); gap: 16px; align-items: start; }
.wp-mx { border-collapse: separate; border-spacing: 3px; font-family: var(--ds-font-mono); font-size: var(--fs-label); text-align: center; width: 100%; }
.wp-mx th { font-weight: 700; color: var(--text-secondary); padding: 4px; }
.wp-mx tbody th { text-align: left; letter-spacing: 0.04em; }
.wp-mx-key { margin-top: 6px; font-family: var(--ds-font-mono); font-size: var(--fs-body); color: var(--text-secondary); }
.wp-tab .wp-sr { position: absolute; }
.wp-mx abbr { text-decoration: none; }
.wp-mx td { box-sizing: border-box; height: 32px; border: 1px solid var(--border); border-radius: var(--ds-r-xs); }
.wp-mx td.wp-lit { color: var(--cyan); font-weight: 700; border-color: var(--cyan); background: var(--cyan-bg); }
.wp-mx thead td { border: 0; }
.wp-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.wp-methods { list-style: none; display: flex; flex-direction: column; border: 1px solid var(--border); border-radius: var(--ds-r-sm); background-color: var(--surface); }
.wp-methods li { display: flex; flex-direction: column; gap: 6px; padding: 10px 12px; }
.wp-methods li + li { border-top: 1px solid var(--border); }
.wp-mmeta { font-size: var(--fs-body); color: var(--text-secondary); align-self: center; }
.wp-mtags { display: flex; flex-wrap: wrap; gap: 6px; }
@container (max-width: 44rem) { .wp-notes, .wp-mx-wrap { grid-template-columns: minmax(0, 1fr); } .wp-crow { grid-template-columns: minmax(0, 1fr); row-gap: 4px; } .wp-tabs { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
@container (max-width: 26rem) { .wp-tab { padding: 6px; } .wp-tab-s { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); } }
.wp-stripwrap:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }
@media only print { .wp-panel[hidden] { display: flex !important; } .wp-tabs, .wp-sw { display: none; } .wp-pm { display: block; } .wp-pm > summary { display: none; } .wp-note, .wp-fork-card, .wp-crow { break-inside: avoid; } .wp-hyp { background-image: none; } }
@media only screen and (prefers-reduced-motion: reduce), only print { .wp * { transition: none !important; } }
/* @prim:end 70-week-plan */
